import { decodeBridgeMessage, decodeEventText } from './utils';

describe('processor-utils', () => {
  it('test decodeBridgeMessage', async () => {
    const res = decodeBridgeMessage(
      '0x7556085E8e6A1Dabbc528fbcA2C7699fA5Ee6e11',
      '0x000000000000000000000000a3d4bee77b05d4a0c943877558ce21a763c4fa2900000000000000000000000000000000000000000000000000000000d09dc300000000000000000000000000ffffffff0000000000000000000000000003b143',
      'inbox',
    );

    expect(res).toMatchObject({
      erc20Value: {
        amount: '3500000000',
        tokenAddress: '0xa3d4BEe77B05d4a0C943877558Ce21A763C4fa29',
      },
    });
  });

  it('test decodeEventText', async () => {
    const res = decodeEventText(
      '',
    );

    expect(res).toMatchObject({
      source: '0x7556085E8e6A1Dabbc528fbcA2C7699fA5Ee6e11',
      message:
        '0x000000000000000000000000a3d4bee77b05d4a0c943877558ce21a763c4fa2900000000000000000000000000000000000000000000000000000000d09dc300000000000000000000000000ffffffff0000000000000000000000000003b143',
    });
  });
});
